// Goals 6–8 runtime screens: Team Chat, Reports, and Agents.

state.chat = state.chat || { loading: false, error: '', channels: [], direct: [], messages: [] };
state.reports = state.reports || { loading: false, error: '', summary: null, agents: [] };
state.agents = state.agents || { loading: false, error: '', items: [] };

function chatMessageList(messages) {
  if (!messages?.length) return '<div class="empty-state"><strong>No messages yet</strong>Start the internal conversation for this channel.</div>';
  return messages.map(message => `<div class="message ${message.sender?.id === state.authUser?.id ? 'mine' : ''}"><div class="person-avatar">${message.sender?.initials || '??'}</div><div class="message-body"><div class="message-meta"><b>${message.sender?.full_name || 'Unknown user'}</b><span>${new Date(message.created_at).toLocaleString(undefined, { hour: 'numeric', minute: '2-digit' })}</span></div><div class="message-bubble">${AureumUI.escape(message.message_text || '')}${message.attachment_name ? `<div class="attachment-preview">📎 ${AureumUI.escape(message.attachment_name)}</div>` : ''}</div></div></div>`).join('');
}

async function loadChat() {
  if (!state.authUser) return;
  state.chat = { ...state.chat, loading: true, error: '' }; render();
  try { const [channels, direct] = await Promise.all([apiFetch('/api/chat/channels'), apiFetch('/api/chat/direct')]); state.chat = { ...state.chat, loading: false, channels: channels.data || [], direct: direct.data || [] }; const active = state.chatActive || { type: 'channel', id: 'channel_sales', name: 'Sales Team' }; if (active.type === 'channel') await openChatChannel(active.id, false); else await openDirectChat(active.id, false); }
  catch (error) { state.chat = { ...state.chat, loading: false, error: error.message }; render(); }
  if (!state.chatTimer) state.chatTimer = window.setInterval(() => { if (state.screen === 'team-chat' && state.authUser && state.chatActive) refreshActiveChat(); }, 5000);
}

async function refreshActiveChat() {
  const active = state.chatActive; if (!active) return;
  try { const result = active.type === 'channel' ? await apiFetch(`/api/chat/channels/${active.id}/messages`) : await apiFetch(`/api/chat/direct/${active.id}/messages`); state.chat.messages = result.data || []; render(); } catch { /* preserve the last visible chat state */ }
}

async function openChatChannel(id, shouldRender = true) {
  const channel = state.chat.channels.find(item => item.id === id); state.chatActive = { type: 'channel', id, name: channel?.name || 'Channel', description: channel?.description || '' }; if (shouldRender) render();
  try { const result = await apiFetch(`/api/chat/channels/${id}/messages`); state.chat.messages = result.data || []; } catch (error) { state.chat.error = error.message; }
  render();
}

async function openDirectChat(id, shouldRender = true) {
  const item = state.chat.direct.find(entry => entry.user.id === id); state.chatActive = { type: 'direct', id, name: item?.user.full_name || 'Direct message', description: `${roleLabels[(item?.user.role || 'sales_agent').toUpperCase()] || 'CRM user'} · ${item?.user.online ? 'Online' : 'Offline'}` }; if (shouldRender) render();
  try { const result = await apiFetch(`/api/chat/direct/${id}/messages`); state.chat.messages = result.data || []; } catch (error) { state.chat.error = error.message; }
  render();
}

function renderChat() {
  const active = state.chatActive || { type: 'channel', id: 'channel_sales', name: 'Sales Team', description: 'Daily sales coordination' };
  const channels = state.chat.channels || [];
  const direct = (state.chat.direct || []).filter(item => !state.chatSearch || item.user.full_name.toLowerCase().includes(state.chatSearch.toLowerCase()));
  const info = active.type === 'channel' ? channels.find(item => item.id === active.id) : direct.find(item => item.user.id === active.id)?.user;
  const members = active.type === 'channel' ? (info?.members || []).map(id => state.chat.direct.find(item => item.user.id === id)?.user || (state.authUser?.id === id ? state.authUser : null)).filter(Boolean) : [info].filter(Boolean);
  const messages = state.chat.loading ? '<div class="empty-state"><strong>Loading conversations</strong>Syncing internal messages…</div>' : state.chat.error ? `<div class="empty-state"><strong>Unable to load chat</strong>${AureumUI.escape(state.chat.error)}<br/><button class="btn btn-secondary btn-sm" data-reload-chat>Retry</button></div>` : chatMessageList(state.chat.messages);
  return `<div class="chat-screen-toolbar"><button class="btn btn-secondary btn-sm" data-reload-chat>Refresh</button></div><section class="chat-layout"><aside class="chat-sidebar"><div class="chat-search">${icons.search}<input data-chat-search placeholder="Search conversations" value="${AureumUI.escape(state.chatSearch || '')}" /></div><div class="chat-label">Channels</div>${channels.map(channel => `<button class="channel ${active.type === 'channel' && active.id === channel.id ? 'active' : ''}" data-chat-channel="${channel.id}"><span># ${AureumUI.escape(channel.name)}</span>${channel.unread ? `<span class="unread">${channel.unread}</span>` : ''}</button>`).join('')}<div class="chat-label">Direct messages</div>${direct.map(item => `<button class="channel ${active.type === 'direct' && active.id === item.user.id ? 'active' : ''}" data-chat-direct="${item.user.id}"><span><i class="online ${item.user.online ? '' : 'offline'}"></i> ${AureumUI.escape(item.user.full_name)}</span>${item.unread ? `<span class="unread">${item.unread}</span>` : ''}</button>`).join('')}</aside><div class="chat-main"><div class="chat-header"><div><div class="chat-channel-title">${active.type === 'channel' ? '# ' : ''}${AureumUI.escape(active.name)}</div><div class="chat-channel-copy">${AureumUI.escape(active.description || 'Internal Aureum communication')}</div></div></div><div class="messages">${messages}</div><form class="chat-compose" id="chat-message-form"><label class="icon-btn aureum-tooltip" data-tooltip="Attach a file"><input type="file" name="attachment" hidden />📎</label><textarea name="message_text" rows="1" placeholder="Message ${active.type === 'channel' ? '#' : ''}${AureumUI.escape(active.name)}" aria-label="Message text"></textarea><button class="btn btn-gold btn-sm" type="submit">Send ${icons.arrow}</button></form></div><aside class="chat-details"><div class="section-title"><div><h3>${active.type === 'channel' ? 'Channel details' : 'User profile'}</h3><p>${AureumUI.escape(active.name)}</p></div></div><p class="page-subtitle">${AureumUI.escape(active.description || 'Internal workspace conversation')}</p><div class="chat-label">${active.type === 'channel' ? 'Members' : 'Status'}</div><div class="member-list">${members.map(member => `<div class="member"><div class="person-avatar">${member.initials || customerInitials(member.full_name)}</div><span>${AureumUI.escape(member.full_name)}</span><i class="online ${member.online === false ? 'offline' : ''}"></i></div>`).join('') || '<div class="empty-state">No member details.</div>'}</div><div class="chat-label">Shared files</div><div class="timeline-copy">Attachments shared in this conversation appear here.</div></aside></section>`;
}

async function sendChatMessage(event) {
  event.preventDefault(); const form = event.currentTarget; const text = form.message_text.value.trim(); const file = form.attachment.files[0]; if (!text && !file) return;
  const body = { message_text: text, attachment_name: file?.name || '' }; const active = state.chatActive;
  try { const endpoint = active.type === 'channel' ? `/api/chat/channels/${active.id}/messages` : `/api/chat/direct/${active.id}/messages`; await apiFetch(endpoint, { method: 'POST', body: JSON.stringify(body) }); form.reset(); await refreshActiveChat(); } catch (error) { showToast(error.message); }
}

async function loadReports() {
  if (!state.authUser || !['SUPER_ADMIN', 'SALES_MANAGER'].includes(state.role)) return;
  state.reports = { ...state.reports, loading: true, error: '' }; render();
  try { const [summary, agents] = await Promise.all([apiFetch('/api/reports/summary'), apiFetch('/api/reports/agents')]); state.reports = { loading: false, error: '', summary: summary.data, agents: agents.data || [] }; } catch (error) { state.reports = { loading: false, error: error.message, summary: null, agents: [] }; }
  render();
}

function performanceBadge(value) { return `<span class="badge ${value === 'Excellent' ? 'badge-completed' : value === 'Good' ? 'badge-hot' : value === 'Needs Attention' ? 'badge-overdue' : 'badge-follow'}">${AureumUI.escape(value)}</span>`; }

function renderReports() {
  const summary = state.reports.summary || {}; const rows = state.reports.agents || [];
  const content = state.reports.loading ? AureumUI.render.loading('Loading management report') : state.reports.error ? AureumUI.render.error('Unable to load reports', state.reports.error, '<button class="btn btn-secondary btn-sm" data-reload-reports>Retry</button>') : `<div class="table-wrap"><table><thead><tr><th>Agent</th><th>Team</th><th>Assigned</th><th>Contacted</th><th>Hot</th><th>Completed</th><th>Overdue</th><th>Closed</th><th>Conversion</th><th>Performance</th><th>Action</th></tr></thead><tbody>${rows.map(row => `<tr><td>${person(row.name, row.initials, row.email)}</td><td>${row.team}</td><td>${row.assignedLeads}</td><td>${row.contactedLeads}</td><td>${row.hotLeads}</td><td>${row.followUpsCompleted}</td><td>${row.overdueFollowUps}</td><td>${row.closedDeals}</td><td><b>${row.conversionRate}</b></td><td>${performanceBadge(row.performance)}</td><td><button class="table-action" data-report-agent="${row.id}">View details ${icons.arrow}</button></td></tr>`).join('')}</tbody></table></div>`;
  return pageHeader('Executive performance', 'Reports', 'Understand agent productivity, conversion, follow-up health, and sales momentum.', '<a class="btn btn-secondary" href="/api/reports/export/pdf">Export PDF</a><a class="btn btn-gold" href="/api/reports/export/excel">Export Excel</a>') + `<section class="filter-bar card" style="margin-bottom:18px"><button class="tab active">Today</button><button class="tab">This week</button><button class="tab">This month</button><button class="tab">Last month</button><button class="btn btn-secondary btn-sm">Custom range</button><button class="btn btn-secondary btn-sm" data-reload-reports>Refresh</button></section><section class="grid grid-4">${kpi('Total agents', String(summary.totalAgents ?? '—'), state.role === 'SALES_MANAGER' ? 'Team scope' : 'Company scope')} ${kpi('Leads assigned', String(summary.assignedLeads ?? '—'), 'Visible workload')} ${kpi('Follow-ups completed', String(summary.followUpsCompleted ?? '—'), 'Resolved touches')} ${kpi('Conversion rate', `${summary.conversionRate ?? 0}%`, `${summary.overdueFollowUps ?? 0} overdue`, 'down')}</section><section class="grid grid-2" style="margin-top:18px"><div class="card chart-card"><div class="section-title"><div><h3>Closed deals by agent</h3><p>Comparison across the permitted team</p></div></div>${rows.map(row => `<div class="progress-row"><span>${row.name}</span><div class="progress-track"><div class="progress-value" style="width:${Math.min(100, row.closedDeals * 12)}%"></div></div><b>${row.closedDeals}</b></div>`).join('') || '<div class="empty-state">No agent data available.</div>'}</div><div class="card chart-card"><div class="section-title"><div><h3>Follow-up completion</h3><p>Completed, pending, overdue, and missed</p></div></div>${[['Completed', summary.followUpsCompleted || 0, 'var(--green)'], ['Pending', summary.followUpsDue || 0, 'var(--gold)'], ['Overdue', summary.overdueFollowUps || 0, 'var(--red)'], ['Lost leads', summary.lostLeads || 0, 'var(--amber)']].map(item => `<div class="progress-row"><span>${item[0]}</span><div class="progress-track"><div class="progress-value" style="width:${Math.min(100, item[1] * 8)}%;background:${item[2]}"></div></div><b>${item[1]}</b></div>`).join('')}</div></section><section class="card table-card" style="margin-top:18px"><div class="table-head"><div><h3>Agent Performance Report</h3><p class="page-subtitle">Click an agent to open the management detail drawer.</p></div></div>${content}</section>`;
}

async function openReportAgent(id) { state.drawer = 'report-agent'; state.reportAgentDetail = null; state.reportAgentTab = 'overview'; render(); try { const [detail, leads, followups, customers, activity] = await Promise.all(['', 'leads', 'follow-ups', 'customers', 'activity'].map(tab => apiFetch(`/api/reports/agents/${id}${tab ? `/${tab}` : ''}`))); state.reportAgentDetail = { data: detail.data, leads: leads.data, followups: followups.data, customers: customers.data, activity: activity.data }; } catch (error) { state.reportAgentDetail = { error: error.message }; } render(); }

function renderReportDrawer() {
  const detail = state.reportAgentDetail; if (!detail) return `<div class="drawer-backdrop" data-close-drawer></div><aside class="drawer"><div class="drawer-header"><h2>Loading report…</h2><button class="drawer-close" data-close-drawer>${icons.close}</button></div>${AureumUI.render.loading('Loading agent details')}</aside>`;
  if (detail.error) return `<div class="drawer-backdrop" data-close-drawer></div><aside class="drawer"><div class="drawer-header"><h2>Access denied</h2><button class="drawer-close" data-close-drawer>${icons.close}</button></div>${AureumUI.render.error('Unable to load agent', detail.error)}</aside>`;
  const a = detail.data; const tab = state.reportAgentTab; const body = tab === 'leads' ? `<div class="timeline">${detail.leads.map(item => `<div class="timeline-item"><div class="timeline-dot"></div><div><b>${item.full_name}</b><div class="timeline-copy">${item.status} · ${item.source}</div></div></div>`).join('') || AureumUI.render.empty('No leads assigned') }</div>` : tab === 'follow-ups' ? `<div class="timeline">${detail.followups.map(item => `<div class="timeline-item"><div class="timeline-dot"></div><div><b>${item.customer}</b><div class="timeline-copy">${item.type} · ${item.due_at} · ${item.status}</div></div></div>`).join('') || AureumUI.render.empty('No follow-ups assigned') }</div>` : tab === 'customers' ? `<div class="timeline">${detail.customers.map(item => `<div class="timeline-item"><div class="timeline-dot"></div><div><b>${item.full_name}</b><div class="timeline-copy">${item.interest} · ${item.status}</div></div></div>`).join('') || AureumUI.render.empty('No customers assigned') }</div>` : tab === 'activity' ? `<div class="timeline">${detail.activity.map(item => `<div class="timeline-item"><div class="timeline-dot"></div><div><b>${item.activity_type}</b><div class="timeline-copy">${item.description}</div></div></div>`).join('') || AureumUI.render.empty('No activity recorded') }</div>` : `<div class="grid grid-2">${kpi('Assigned leads', a.assignedLeads)}${kpi('Closed deals', a.closedDeals)}${kpi('Follow-ups done', a.followUpsCompleted)}${kpi('Conversion', a.conversionRate)}</div><div class="drawer-section">${performanceBadge(a.performance)} <span class="page-subtitle">${a.role} · ${a.team}</span></div>`;
  return `<div class="drawer-backdrop" data-close-drawer></div><aside class="drawer"><div class="drawer-header"><div><div class="eyebrow">Agent performance</div><h2>${AureumUI.escape(a.name)}</h2><p class="page-subtitle">${AureumUI.escape(a.email)} · ${performanceBadge(a.performance)}</p></div><button class="drawer-close" data-close-drawer>${icons.close}</button></div><div class="drawer-section"><div class="header-actions"><button class="btn btn-gold btn-sm" data-agent-message="${a.id}">Message</button><button class="btn btn-secondary btn-sm" data-agent-leads="${a.id}">View leads</button></div></div><div class="tabs" style="padding:0">${['overview', 'leads', 'follow-ups', 'customers', 'activity'].map(item => `<button class="tab ${tab === item ? 'active' : ''}" data-report-tab="${item}">${item[0].toUpperCase() + item.slice(1)}</button>`).join('')}</div><div class="drawer-section">${body}</div></aside>`;
}

async function loadAgents() { if (!state.authUser || !['SUPER_ADMIN', 'SALES_MANAGER'].includes(state.role)) return; state.agents = { ...state.agents, loading: true, error: '' }; render(); try { const result = await apiFetch('/api/agents'); state.agents = { loading: false, error: '', items: result.data || [] }; } catch (error) { state.agents = { loading: false, error: error.message, items: [] }; } render(); }

function renderAgentForm() { const canCreateManager = state.role === 'SUPER_ADMIN'; return `<div class="drawer-backdrop" data-close-drawer></div><aside class="drawer"><div class="drawer-header"><div><div class="eyebrow">Workspace people</div><h2>Add agent</h2></div><button class="drawer-close" data-close-drawer>${icons.close}</button></div><form id="add-agent-form"><div class="drawer-section"><div class="form-field"><label>Full name</label><input name="full_name" required /></div><div class="form-field"><label>Email</label><input name="email" type="email" required /></div><div class="form-field"><label>Phone</label><input name="phone" /></div><div class="form-field"><label>Role</label><select name="role">${canCreateManager ? '<option value="sales_manager">Sales Manager</option>' : ''}<option value="sales_agent">Sales Agent</option></select></div><div class="form-field"><label>Team</label><select name="team_id"><option value="team_a">Sales Team A</option><option value="team_b">Sales Team B</option></select></div><div class="form-field"><label>Temporary password</label><input name="password" type="password" required value="Aureum123!" /></div></div><div class="drawer-section"><button class="btn btn-gold" type="submit">Create user</button></div></form></aside>`; }

async function openAgent(id) { state.drawer = 'agent'; state.agentDetail = null; state.agentTab = 'overview'; render(); try { const [detail, leads, followups, customers, activity] = await Promise.all(['', 'leads', 'follow-ups', 'customers', 'activity'].map(tab => apiFetch(`/api/agents/${id}${tab ? `/${tab}` : ''}`))); state.agentDetail = { data: detail.data, leads: leads.data, followups: followups.data, customers: customers.data, activity: activity.data }; } catch (error) { state.agentDetail = { error: error.message }; } render(); }

function renderAgentDrawer() { const detail = state.agentDetail; if (!detail) return `<div class="drawer-backdrop" data-close-drawer></div><aside class="drawer"><div class="drawer-header"><h2>Loading agent…</h2><button class="drawer-close" data-close-drawer>${icons.close}</button></div>${AureumUI.render.loading('Loading user profile')}</aside>`; if (detail.error) return `<div class="drawer-backdrop" data-close-drawer></div><aside class="drawer"><div class="drawer-header"><h2>Access denied</h2><button class="drawer-close" data-close-drawer>${icons.close}</button></div>${AureumUI.render.error('Unable to load agent', detail.error)}</aside>`; const a = detail.data; const tab = state.agentTab; const body = tab === 'leads' ? detail.leads.map(item => `<div class="source-row"><b>${item.full_name}</b><span>${badge(item.status)}</span></div>`).join('') : tab === 'follow-ups' ? detail.followups.map(item => `<div class="source-row"><b>${item.customer}</b><span>${badge(item.status)}</span></div>`).join('') : tab === 'customers' ? detail.customers.map(item => `<div class="source-row"><b>${item.full_name}</b><span>${badge(item.status)}</span></div>`).join('') : tab === 'activity' ? detail.activity.map(item => `<div class="timeline-item"><div class="timeline-dot"></div><div><b>${item.activity_type}</b><div class="timeline-copy">${item.description}</div></div></div>`).join('') : `<div class="grid grid-2">${kpi('Assigned leads', a.assignedLeads)}${kpi('Active leads', a.activeLeads)}${kpi('Follow-ups due', a.followUpsDue)}${kpi('Overdue', a.overdueFollowUps)}${kpi('Closed deals', a.closedDeals)}${kpi('Conversion', a.conversionRate)}</div><form id="edit-agent-form" class="drawer-section"><div class="form-field"><label>Full name</label><input name="full_name" value="${AureumUI.escape(a.full_name)}" required /></div><div class="form-field"><label>Phone</label><input name="phone" value="${AureumUI.escape(a.phone || '')}" /></div><div class="form-field"><label>Status</label><select name="status"><option value="active" ${a.status === 'active' ? 'selected' : ''}>Active</option><option value="inactive" ${a.status === 'inactive' ? 'selected' : ''}>Inactive</option></select></div><button class="btn btn-gold" type="submit">Save changes</button></form>`; return `<div class="drawer-backdrop" data-close-drawer></div><aside class="drawer"><div class="drawer-header"><div><div class="eyebrow">Agent management</div><h2>${AureumUI.escape(a.full_name)}</h2><p class="page-subtitle">${roleLabels[a.role.toUpperCase()] || a.role} · ${a.team || 'Unassigned'} · ${badge(a.status)}</p></div><button class="drawer-close" data-close-drawer>${icons.close}</button></div><div class="drawer-section"><div class="header-actions"><button class="btn btn-gold btn-sm" data-agent-message="${a.id}">Message</button><button class="btn btn-secondary btn-sm" data-agent-report="${a.id}">View report</button></div></div><div class="tabs" style="padding:0">${['overview', 'leads', 'follow-ups', 'customers', 'activity'].map(item => `<button class="tab ${tab === item ? 'active' : ''}" data-agent-tab="${item}">${item[0].toUpperCase() + item.slice(1)}</button>`).join('')}</div><div class="drawer-section">${body}</div></aside>`; }

function renderAgents() { const all = state.agents.items || []; const query = String(state.agentSearch || '').toLowerCase(); const items = all.filter(item => !query || [item.full_name, item.email, item.phone, item.role, item.team].some(value => String(value || '').toLowerCase().includes(query))).filter(item => !state.agentRoleFilter || item.role === state.agentRoleFilter).filter(item => !state.agentStatusFilter || item.status === state.agentStatusFilter); const summary = { total: all.length, active: all.filter(item => item.status === 'active').length, inactive: all.filter(item => item.status !== 'active').length, managers: all.filter(item => item.role === 'sales_manager').length }; const content = state.agents.loading ? AureumUI.render.loading('Loading team users') : state.agents.error ? AureumUI.render.error('Unable to load agents', state.agents.error, '<button class="btn btn-secondary btn-sm" data-reload-agents>Retry</button>') : `<div class="table-wrap"><table><thead><tr><th>Agent</th><th>Team</th><th>Role</th><th>Assigned leads</th><th>Active leads</th><th>Closed</th><th>Follow-ups due</th><th>Status</th><th>Action</th></tr></thead><tbody>${items.map(item => `<tr><td>${person(item.full_name, item.initials, `${item.email} · ${item.phone || 'No phone'}`)}</td><td>${item.team || 'Unassigned'}</td><td>${badge(roleLabels[item.role.toUpperCase()] || item.role)}</td><td>${item.assignedLeads}</td><td>${item.activeLeads}</td><td>${item.closedDeals}</td><td>${item.followUpsDue}</td><td>${badge(item.status === 'active' ? 'Active' : 'Inactive')}</td><td><button class="table-action" data-agent-open="${item.id}">View ${icons.arrow}</button></td></tr>`).join('')}</tbody></table></div>`; return pageHeader('People and permissions', 'Agents', 'Manage team users, workload, role scope, and activity without leaving the sales workspace.', '<button class="btn btn-gold" data-create-agent>+ Add agent</button>') + `<section class="grid grid-4">${kpi('Total users', summary.total, state.role === 'SALES_MANAGER' ? 'Team scope' : 'Company scope')} ${kpi('Active agents', summary.active, 'Available')} ${kpi('Inactive users', summary.inactive, 'Historical access retained')} ${kpi('Sales managers', summary.managers, 'Leadership')}</section><section class="card table-card" style="margin-top:18px"><div class="filter-bar"><div class="search-box">${icons.search}<input data-agent-search value="${AureumUI.escape(state.agentSearch || '')}" placeholder="Search name, phone, email" /></div><select class="select" data-agent-role><option value="">All roles</option><option value="sales_manager">Sales Manager</option><option value="sales_agent">Sales Agent</option></select><select class="select" data-agent-status><option value="">All statuses</option><option value="active">Active</option><option value="inactive">Inactive</option></select><button class="btn btn-secondary btn-sm" data-reload-agents>Refresh</button></div>${content}</section>`; }

function renderDrawer() { if (state.drawer === 'customer') return window.renderCustomerDrawer ? window.renderCustomerDrawer() : renderCustomerDrawer(); if (state.drawer === 'followup' || state.drawer === 'create-followup') return window.renderFollowupDrawer ? window.renderFollowupDrawer() : renderFollowupDrawer(); if (state.drawer === 'lead') return window.renderLeadDrawer ? window.renderLeadDrawer() : renderLeadDrawer(); if (state.drawer === 'report-agent') return renderReportDrawer(); if (state.drawer === 'agent') return renderAgentDrawer(); if (state.drawer === 'create-agent') return renderAgentForm(); return legacyRenderDrawer(); }

function navigate(screen) { if (routePaths[screen]) window.history.pushState({}, '', routePaths[screen]); if (!canAccess(screen)) { state.drawer = null; state.deniedPath = screen; state.screen = 'unauthorized'; } else { state.drawer = null; state.screen = screen; } render(); if (screen === 'dashboard') loadDashboard(); if (screen === 'leads') loadLeads(false); if (screen === 'my-leads') loadLeads(true); if (screen === 'customers') loadCustomers(); if (screen === 'follow-ups') loadFollowups(); if (screen === 'team-chat') loadChat(); if (screen === 'reports') loadReports(); if (screen === 'agents') loadAgents(); }

function bind() {
  window.aureumFinalBind();
  document.querySelectorAll('[data-reload-chat]').forEach(el => el.addEventListener('click', loadChat));
  document.querySelectorAll('[data-chat-channel]').forEach(el => el.addEventListener('click', () => openChatChannel(el.dataset.chatChannel)));
  document.querySelectorAll('[data-chat-direct]').forEach(el => el.addEventListener('click', () => openDirectChat(el.dataset.chatDirect)));
  const chatSearch = document.querySelector('[data-chat-search]'); if (chatSearch) chatSearch.addEventListener('input', AureumUI.debounce(event => { state.chatSearch = event.target.value; render(); }, 180));
  const chatForm = document.querySelector('#chat-message-form'); if (chatForm) chatForm.addEventListener('submit', sendChatMessage);
  document.querySelectorAll('[data-reload-reports]').forEach(el => el.addEventListener('click', loadReports));
  document.querySelectorAll('[data-report-agent]').forEach(el => el.addEventListener('click', () => openReportAgent(el.dataset.reportAgent)));
  document.querySelectorAll('[data-report-tab]').forEach(el => el.addEventListener('click', () => { state.reportAgentTab = el.dataset.reportTab; render(); }));
  document.querySelectorAll('[data-agent-open]').forEach(el => el.addEventListener('click', () => openAgent(el.dataset.agentOpen)));
  document.querySelectorAll('[data-create-agent]').forEach(el => el.addEventListener('click', () => { state.drawer = 'create-agent'; render(); }));
  document.querySelectorAll('[data-reload-agents]').forEach(el => el.addEventListener('click', loadAgents));
  document.querySelectorAll('[data-agent-tab]').forEach(el => el.addEventListener('click', () => { state.agentTab = el.dataset.agentTab; render(); }));
  document.querySelectorAll('[data-agent-message]').forEach(el => el.addEventListener('click', () => { state.drawer = null; state.screen = 'team-chat'; state.chatActive = { type: 'direct', id: el.dataset.agentMessage }; render(); loadChat().then(() => openDirectChat(el.dataset.agentMessage)); }));
  document.querySelectorAll('[data-agent-report]').forEach(el => el.addEventListener('click', () => { state.drawer = 'report-agent'; openReportAgent(el.dataset.agentReport); }));
  const agentSearch = document.querySelector('[data-agent-search]'); if (agentSearch) agentSearch.addEventListener('input', AureumUI.debounce(event => { state.agentSearch = event.target.value; render(); }, 180));
  const agentRole = document.querySelector('[data-agent-role]'); if (agentRole) agentRole.addEventListener('change', event => { state.agentRoleFilter = event.target.value; render(); });
  const agentStatus = document.querySelector('[data-agent-status]'); if (agentStatus) agentStatus.addEventListener('change', event => { state.agentStatusFilter = event.target.value; render(); });
  const addAgentForm = document.querySelector('#add-agent-form'); if (addAgentForm) addAgentForm.addEventListener('submit', async event => { event.preventDefault(); const data = Object.fromEntries(new FormData(addAgentForm).entries()); try { await apiFetch('/api/agents', { method: 'POST', body: JSON.stringify(data) }); state.drawer = null; await loadAgents(); showToast('Agent created'); } catch (error) { showToast(error.message); } });
  const editAgentForm = document.querySelector('#edit-agent-form'); if (editAgentForm) editAgentForm.addEventListener('submit', async event => { event.preventDefault(); const data = Object.fromEntries(new FormData(editAgentForm).entries()); try { await apiFetch(`/api/agents/${state.agentDetail.data.id}`, { method: 'PATCH', body: JSON.stringify(data) }); await openAgent(state.agentDetail.data.id); await loadAgents(); showToast('Agent updated'); } catch (error) { showToast(error.message); } });
}

/* Module 6 enhanced workspace: channels, groups, direct messages, and a closed-by-default info panel. */
state.chat = { loading: false, error: '', channels: [], groups: [], direct: [], users: [], messages: [], attachments: [], links: [], unread: {}, ...(state.chat || {}) };
state.chatRightInfoOpen = Boolean(state.chatRightInfoOpen);
state.chatSidebarOpen = Boolean(state.chatSidebarOpen);
state.chatGroupModalOpen = Boolean(state.chatGroupModalOpen);
state.chatGroupDraft = state.chatGroupDraft || { groupName: '', description: '', memberIds: [] };

function chatApiBase(type) { return type === 'channel' ? 'channels' : type === 'group' ? 'groups' : 'direct'; }
function activeChatEntry() { const active = state.chatActive || {}; if (active.type === 'channel') return state.chat.channels.find(item => item.id === active.id); if (active.type === 'group') return state.chat.groups.find(item => item.id === active.id); return state.chat.direct.find(item => item.user?.id === active.id)?.user; }
function chatRoleName(role) { return roleLabels[String(role || '').toUpperCase()] || String(role || '').replaceAll('_', ' '); }
function chatPresenceLabel(user) { return user?.online ? 'Online' : 'Offline'; }
function chatInitials(user) { return user?.initials || user?.full_name?.split(' ').map(part => part[0]).slice(0, 2).join('').toUpperCase() || 'AU'; }
function chatLastPreview(item) { return item?.lastMessage?.body || item?.lastMessage || 'Start a conversation'; }
function chatSearchMatch(item, query) { return !query || [item?.name, item?.groupName, item?.user?.full_name, chatLastPreview(item)].some(value => String(value || '').toLowerCase().includes(query)); }

function renderEnhancedMessageList(messages) {
  if (!messages?.length) return '<div class="empty-state chat-empty-state"><strong>No messages yet</strong>Start the internal conversation for this chat.</div>';
  let previousDay = '';
  return messages.map(message => {
    const created = message.created_at || message.createdAt || new Date().toISOString(); const day = new Date(created).toDateString(); const separator = day !== previousDay ? `<div class="chat-date-separator"><span>${new Date(created).toLocaleDateString([], { month: 'short', day: 'numeric', year: 'numeric' })}</span></div>` : ''; previousDay = day;
    const sender = message.sender || {}; const own = sender.id === state.authUser?.id || message.sender_id === state.authUser?.id; const system = message.message_type === 'system';
    const attachment = message.attachment_name ? `<div class="attachment-preview"><span class="attachment-icon">📎</span><span><b>${AureumUI.escape(message.attachment_name)}</b>${message.attachment_url ? `<a href="${AureumUI.escape(message.attachment_url)}" download="${AureumUI.escape(message.attachment_name)}">Download attachment</a>` : '<small>Attachment metadata recorded</small>'}</span></div>` : '';
    if (system) return `${separator}<div class="chat-system-message">${AureumUI.escape(message.message_text || '')}</div>`;
    return `${separator}<article class="message ${own ? 'mine' : ''}"><div class="person-avatar">${AureumUI.escape(chatInitials(sender))}</div><div class="message-body"><div class="message-meta"><b>${AureumUI.escape(sender.full_name || 'Aureum user')}</b><span>${AureumUI.escape(chatRoleName(sender.role))}</span><time>${new Date(created).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })}</time></div><div class="message-bubble">${AureumUI.escape(message.message_text || message.body || '')}${attachment}</div></div></article>`;
  }).join('');
}
function renderChatSidebarSection(title, content, action = '') { return `<div class="chat-sidebar-section"><div class="chat-section-heading"><span>${title}</span>${action}</div>${content || '<div class="chat-sidebar-empty">Nothing here yet.</div>'}</div>`; }
function renderChatListItem({ id, type, label, preview, unread, active, presence, icon }) { return `<button class="channel chat-list-item ${active ? 'active' : ''}" data-chat-${type}="${AureumUI.escape(id)}"><span class="chat-list-copy"><span class="chat-list-title">${icon || ''}${AureumUI.escape(label)}</span><small>${AureumUI.escape(preview || '')}</small></span><span class="chat-list-meta">${presence ? `<i class="presence-dot ${presence}"></i>` : ''}${unread ? `<span class="unread">${unread}</span>` : ''}</span></button>`; }

function renderChatInfoPanel(active) {
  const entry = activeChatEntry() || {}; const members = entry.members || (active.type === 'channel' ? (entry.memberIds || []).map(id => state.chat.users.find(user => user.id === id) || (state.authUser?.id === id ? state.authUser : null)).filter(Boolean) : [entry].filter(item => item?.id)); const canManage = Boolean(entry.canManage); const files = state.chat.attachments || []; const links = state.chat.links || [];
  const membersMarkup = members.map(member => `<div class="member chat-info-member"><div class="person-avatar">${AureumUI.escape(chatInitials(member))}</div><div><b>${AureumUI.escape(member.full_name || member.fullName || 'Aureum user')}</b><small>${AureumUI.escape(chatRoleName(member.role))} · ${AureumUI.escape(member.team_name || member.teamName || 'Aureum workspace')}</small></div><i class="presence-dot ${member.online === false || member.presenceStatus === 'offline' ? 'offline' : member.presenceStatus === 'away' ? 'away' : 'online'}"></i>${canManage && member.id !== entry.createdBy ? `<button class="table-action chat-remove-member" data-chat-remove-member="${AureumUI.escape(member.id)}" title="Remove member" aria-label="Remove ${AureumUI.escape(member.full_name || member.fullName || 'member')} from group">×</button>` : ''}</div>`).join('') || '<div class="chat-sidebar-empty">No members listed.</div>';
  const fileMarkup = files.map(file => `<div class="shared-asset"><span class="asset-icon">📎</span><div><b>${file.attachment_url ? `<a href="${AureumUI.escape(file.attachment_url)}" download="${AureumUI.escape(file.fileName || file.file_name)}">${AureumUI.escape(file.fileName || file.file_name)}</a>` : AureumUI.escape(file.fileName || file.file_name)}</b><small>${AureumUI.escape(file.fileType || file.file_type || 'file')} · ${AureumUI.escape(file.fileSize || file.file_size || 'Size pending')}</small></div></div>`).join('') || '<div class="chat-sidebar-empty">No attachments shared yet.</div>';
  const linkMarkup = links.map(link => `<a class="shared-link" href="${AureumUI.escape(link.url)}" target="_blank" rel="noreferrer"><b>${AureumUI.escape(link.title)}</b><small>${AureumUI.escape(link.sharedByName || 'Aureum user')}</small></a>`).join('') || '<div class="chat-sidebar-empty">No links shared yet.</div>';
  const memberManager = active.type === 'group' && canManage ? `<div class="chat-member-manager"><div class="chat-label">Add members</div>${(state.chat.users || []).filter(user => !members.some(member => member.id === user.id)).map(user => `<label><input type="checkbox" data-chat-member-add="${AureumUI.escape(user.id)}" /> ${AureumUI.escape(user.full_name)} <small>${AureumUI.escape(chatRoleName(user.role))}</small></label>`).join('') || '<small>Everyone in scope is already included.</small>'}<button class="btn btn-secondary btn-sm" data-chat-add-members>Save members</button></div>` : '';
  const management = active.type === 'group' && canManage ? `<section class="chat-group-management"><div class="chat-label">Group management</div><p>Manage members and group details.</p>${memberManager}<div class="chat-info-actions"><button class="btn btn-secondary btn-sm" data-chat-rename>Rename group</button><button class="btn btn-danger btn-sm" data-chat-archive>Delete group</button></div></section>` : '';
  return `<aside class="chat-details chat-info-panel" aria-label="Chat details"><div class="chat-info-header"><div><div class="eyebrow">${active.type === 'channel' ? 'Channel details' : active.type === 'group' ? 'Group details' : 'Direct message'}</div><h2>${active.type === 'channel' ? '# ' : ''}${AureumUI.escape(active.name)}</h2></div><button class="drawer-close" data-chat-close-info aria-label="Close chat details">${icons.close}</button></div><p class="page-subtitle">${AureumUI.escape(active.description || 'Internal Aureum communication')}</p>${management}<div class="chat-info-section"><div class="chat-label">${active.type === 'direct' ? 'Profile' : `Members · ${members.length}`}</div>${membersMarkup}</div><div class="chat-info-section"><div class="chat-label">Shared files</div>${fileMarkup}</div><div class="chat-info-section"><div class="chat-label">Shared links</div>${linkMarkup}<button class="btn btn-secondary btn-sm" data-chat-share-link>Share CRM link</button></div><div class="chat-info-section"><div class="chat-label">CRM references</div><div class="chat-sidebar-empty">Share a CRM record link here so the whole conversation can open the same lead, customer, or follow-up.</div></div></aside>`;
}

function renderCreateGroupModal() { if (!state.chatGroupModalOpen) return ''; const draft = state.chatGroupDraft; const users = state.chat.users || []; const selected = new Set(draft.memberIds || []); return `<div class="chat-modal-backdrop" data-chat-close-modal></div><section class="chat-modal" role="dialog" aria-modal="true" aria-labelledby="create-group-title"><div class="chat-modal-header"><div><div class="eyebrow">New internal conversation</div><h2 id="create-group-title">Create group chat</h2><p class="page-subtitle">Bring the right sales team members into one focused workspace.</p></div><button class="drawer-close" data-chat-close-modal aria-label="Close create group">${icons.close}</button></div><form id="create-group-chat-form"><div class="form-field"><label for="chat-group-name">Group name</label><input id="chat-group-name" name="groupName" required value="${AureumUI.escape(draft.groupName)}" placeholder="e.g. Lahore Leads" /></div><div class="form-field"><label for="chat-group-description">Description</label><textarea id="chat-group-description" name="description" rows="3" placeholder="What is this group for?">${AureumUI.escape(draft.description)}</textarea></div><div class="chat-member-selector"><div class="chat-label">Add members</div>${users.map(user => `<label class="chat-member-option"><input type="checkbox" data-chat-member-toggle="${AureumUI.escape(user.id)}" ${selected.has(user.id) ? 'checked' : ''} ${user.id === state.authUser?.id ? 'disabled' : ''} /><span class="person-avatar">${AureumUI.escape(chatInitials(user))}</span><span><b>${AureumUI.escape(user.full_name)}</b><small>${AureumUI.escape(chatRoleName(user.role))} · ${AureumUI.escape(user.team_name || 'Aureum workspace')}</small></span><i class="presence-dot ${user.online ? 'online' : 'offline'}"></i></label>`).join('') || '<div class="chat-sidebar-empty">No eligible users found.</div>'}</div><div class="chat-modal-footer"><button type="button" class="btn btn-secondary" data-chat-close-modal>Cancel</button><button type="submit" class="btn btn-gold">Create group</button></div></form></section>`; }
function chatActiveDescriptor() { const active = state.chatActive || { type: 'channel', id: 'channel_sales' }; const entry = activeChatEntry() || {}; return { ...active, name: active.name || entry.name || entry.groupName || entry.full_name || 'Team Chat', description: active.description || entry.description || (active.type === 'direct' ? `${chatRoleName(entry.role)} · ${chatPresenceLabel(entry)}` : 'Internal Aureum communication'), memberCount: entry.memberCount || entry.members?.length || entry.memberIds?.length || 0 }; }

async function loadActiveChatData(shouldRender = true) { const active = chatActiveDescriptor(); state.chatActive = active; try { const result = await apiFetch(`/api/chat/${chatApiBase(active.type)}/${active.id}/messages`); state.chat.messages = result.data || []; const [attachments, links] = await Promise.all([apiFetch(`/api/chat/${active.id}/attachments`).catch(() => ({ data: [] })), apiFetch(`/api/chat/${active.id}/links`).catch(() => ({ data: [] }))]); state.chat.attachments = attachments.data || []; state.chat.links = links.data || []; } catch (error) { state.chat.error = error.message; } if (shouldRender) render(); }
async function loadChat() { if (!state.authUser) return; state.chat = { ...state.chat, loading: true, error: '' }; render(); try { const [channels, groups, direct, users, unread] = await Promise.all([apiFetch('/api/chat/channels'), apiFetch('/api/chat/groups'), apiFetch('/api/chat/direct'), apiFetch('/api/chat/users'), apiFetch('/api/chat/unread-counts')]); state.chat = { ...state.chat, loading: false, channels: channels.data || [], groups: groups.data || [], direct: direct.data || [], users: users.data || [], unread: unread.data || {} }; const current = state.chatActive; const valid = current && (current.type === 'channel' ? state.chat.channels.some(item => item.id === current.id) : current.type === 'group' ? state.chat.groups.some(item => item.id === current.id) : state.chat.direct.some(item => item.user.id === current.id)); state.chatActive = valid ? current : { type: 'channel', id: state.chat.channels[0]?.id || 'channel_general' }; await loadActiveChatData(false); } catch (error) { state.chat = { ...state.chat, loading: false, error: error.message }; } ensureEnhancedChatEvents(); render(); if (!state.chatTimer) state.chatTimer = window.setInterval(() => { if (state.screen === 'team-chat' && state.authUser && state.chatActive) refreshActiveChat(); }, 10000); }
async function refreshActiveChat() { if (state.chatActive) await loadActiveChatData(true); }
async function openChatChannel(id, shouldRender = true) { state.chatRightInfoOpen = false; state.chatSidebarOpen = false; state.chatActive = { type: 'channel', id }; if (shouldRender) render(); await loadActiveChatData(true); }
async function openChatGroup(id) { state.chatRightInfoOpen = false; state.chatSidebarOpen = false; state.chatActive = { type: 'group', id }; render(); await loadActiveChatData(true); }
async function openDirectChat(id, shouldRender = true) { state.chatRightInfoOpen = false; state.chatSidebarOpen = false; state.chatActive = { type: 'direct', id }; if (shouldRender) render(); await loadActiveChatData(true); }

function renderChat() { ensureEnhancedChatEvents(); const active = chatActiveDescriptor(); const query = String(state.chatSearch || '').toLowerCase(); const channels = (state.chat.channels || []).filter(item => chatSearchMatch(item, query)); const groups = (state.chat.groups || []).filter(item => chatSearchMatch(item, query)); const direct = (state.chat.direct || []).filter(item => chatSearchMatch(item, query)); const messages = state.chat.loading ? '<div class="empty-state"><strong>Loading conversations</strong>Syncing internal messages…</div>' : state.chat.error ? `<div class="empty-state"><strong>Unable to load chat</strong>${AureumUI.escape(state.chat.error)}<br/><button class="btn btn-secondary btn-sm" data-reload-chat>Retry</button></div>` : renderEnhancedMessageList(state.chat.messages); const channelMarkup = channels.map(item => renderChatListItem({ id: item.id, type: 'channel', label: `# ${item.name}`, preview: chatLastPreview(item), unread: item.unread, active: active.type === 'channel' && active.id === item.id })).join(''); const groupMarkup = groups.map(item => renderChatListItem({ id: item.id, type: 'group', label: item.groupName, preview: chatLastPreview(item), unread: item.unreadCount, active: active.type === 'group' && active.id === item.id, icon: '<span class="chat-item-symbol">◈</span>' })).join(''); const directMarkup = direct.map(item => renderChatListItem({ id: item.user.id, type: 'direct', label: item.user.full_name, preview: item.lastMessage, unread: item.unread, active: active.type === 'direct' && active.id === item.user.id, presence: item.user.online ? 'online' : 'offline' })).join(''); const createAction = ['SUPER_ADMIN', 'SALES_MANAGER'].includes(state.role) ? '<button class="chat-section-action" data-chat-create-group aria-label="Create group chat">+</button>' : ''; const panel = state.chatRightInfoOpen ? renderChatInfoPanel(active) : ''; return `<div class="chat-screen-toolbar"><button class="btn btn-secondary btn-sm" data-reload-chat>Refresh</button></div><section class="chat-layout chat-workspace ${state.chatRightInfoOpen ? 'chat-layout-panel-open' : ''} ${state.chatSidebarOpen ? 'chat-sidebar-mobile-open' : ''}"><aside class="chat-sidebar"><div class="chat-mobile-sidebar-head"><b>Chat workspace</b><button class="drawer-close" data-chat-sidebar-close aria-label="Close chat sidebar">${icons.close}</button></div><div class="chat-search">${icons.search}<input data-chat-search placeholder="Search chat" value="${AureumUI.escape(state.chatSearch || '')}" /></div>${renderChatSidebarSection('Channels', channelMarkup)}${renderChatSidebarSection('Group chats', groupMarkup, createAction)}${renderChatSidebarSection('Direct messages', directMarkup)}<div class="chat-sidebar-footer"><span class="presence-dot online"></span> Live presence · ${state.chat.users?.length || 0} users</div></aside>${state.chatSidebarOpen ? '<div class="chat-sidebar-backdrop" data-chat-sidebar-close></div>' : ''}<main class="chat-main"><div class="chat-header chat-header-button" data-chat-info role="button" tabindex="0" aria-label="Open chat details"><div class="chat-header-leading"><button type="button" class="mobile-chat-toggle" data-chat-sidebar-toggle aria-label="Open chat list">☰</button><div><div class="chat-channel-title">${active.type === 'channel' ? '# ' : ''}${AureumUI.escape(active.name)}</div><div class="chat-channel-copy">${AureumUI.escape(active.description)} · ${active.memberCount || 0} members</div></div></div><span class="chat-info-trigger">ⓘ</span></div><div class="messages">${messages}</div><form class="chat-compose" id="chat-message-form"><label class="icon-btn aureum-tooltip" data-tooltip="Attach a file" for="chat-attachment-input">📎</label><input id="chat-attachment-input" type="file" name="attachment" data-chat-attachment hidden /><span class="chat-file-name" data-chat-file-name></span><textarea name="message_text" rows="1" placeholder="Type your message..." aria-label="Message text"></textarea><button class="btn btn-gold btn-sm" type="submit">Send ${icons.arrow}</button></form></main>${panel}</section>${renderCreateGroupModal()}`; }
function readChatFile(file) { return new Promise((resolve, reject) => { if (!file) return resolve(null); if (file.size > 1500000) return reject(new Error('Attachments must be 1.5 MB or smaller in this workspace.')); const reader = new FileReader(); reader.onload = () => resolve({ name: file.name, size: file.size, type: file.type || 'application/octet-stream', data: reader.result }); reader.onerror = () => reject(new Error('The attachment could not be read.')); reader.readAsDataURL(file); }); }
async function sendChatMessage(event) { event.preventDefault(); const form = event.currentTarget; const text = form.message_text.value.trim(); const file = form.attachment.files[0]; if (!text && !file) return; const active = state.chatActive; try { const attachment = await readChatFile(file); await apiFetch(`/api/chat/${chatApiBase(active.type)}/${active.id}/messages`, { method: 'POST', body: JSON.stringify({ message_text: text, attachment_name: attachment?.name || '', attachment_size: attachment?.size || 0, attachment_mime: attachment?.type || '', attachment_content: attachment?.data || '' }) }); form.reset(); const fileName = document.querySelector('[data-chat-file-name]'); if (fileName) fileName.textContent = ''; await refreshActiveChat(); } catch (error) { showToast(`Unable to send message: ${error.message}`); } }

function ensureEnhancedChatEvents() { if (state.chatEnhancedEventsBound) return; state.chatEnhancedEventsBound = true; document.addEventListener('click', async event => { const target = event.target instanceof Element ? event.target.closest('[data-chat-group], [data-chat-info], [data-chat-close-info], [data-chat-create-group], [data-chat-close-modal], [data-chat-sidebar-toggle], [data-chat-sidebar-close], [data-chat-rename], [data-chat-archive], [data-chat-add-members], [data-chat-remove-member], [data-chat-share-link]') : null; if (!target) return; if (target.matches('[data-chat-group]')) { await openChatGroup(target.dataset.chatGroup); return; } if (target.matches('[data-chat-info]') || target.matches('[data-chat-close-info]')) { state.chatRightInfoOpen = target.matches('[data-chat-info]'); render(); return; } if (target.matches('[data-chat-create-group]')) { state.chatGroupDraft = { groupName: '', description: '', memberIds: [state.authUser?.id].filter(Boolean) }; state.chatGroupModalOpen = true; render(); return; } if (target.matches('[data-chat-close-modal]')) { state.chatGroupModalOpen = false; render(); return; } if (target.matches('[data-chat-sidebar-toggle]')) { state.chatSidebarOpen = true; render(); return; } if (target.matches('[data-chat-sidebar-close]')) { state.chatSidebarOpen = false; render(); return; } if (target.matches('[data-chat-rename]')) { const name = window.prompt('Rename this group', activeChatDescriptor().name); if (name?.trim()) { try { await apiFetch(`/api/chat/groups/${state.chatActive.id}`, { method: 'PATCH', body: JSON.stringify({ groupName: name.trim() }) }); await loadChat(); state.chatRightInfoOpen = true; render(); } catch (error) { showToast(error.message); } } return; } if (target.matches('[data-chat-archive]')) { if (!window.confirm('Archive this group chat?')) return; try { await apiFetch(`/api/chat/groups/${state.chatActive.id}/archive`, { method: 'PATCH' }); state.chatActive = null; state.chatRightInfoOpen = false; await loadChat(); } catch (error) { showToast(error.message); } return; } if (target.matches('[data-chat-add-members]')) { const ids = [...document.querySelectorAll('[data-chat-member-add]:checked')].map(input => input.dataset.chatMemberAdd); if (!ids.length) { showToast('Select at least one member in the group panel.'); return; } try { await apiFetch(`/api/chat/groups/${state.chatActive.id}/members`, { method: 'POST', body: JSON.stringify({ memberIds: ids }) }); await loadChat(); state.chatRightInfoOpen = true; render(); } catch (error) { showToast(error.message); } return; } if (target.matches('[data-chat-share-link]')) { const title = window.prompt('CRM reference title', 'CRM record'); const url = window.prompt('CRM record URL', `${window.location.origin}/dashboard`); if (!title?.trim() || !url?.trim()) return; try { await apiFetch(`/api/chat/${state.chatActive.id}/links`, { method: 'POST', body: JSON.stringify({ title: title.trim(), url: url.trim() }) }); await refreshActiveChat(); state.chatRightInfoOpen = true; render(); } catch (error) { showToast(`Unable to share CRM link: ${error.message}`); } return; } if (target.matches('[data-chat-remove-member]')) { try { await apiFetch(`/api/chat/groups/${state.chatActive.id}/members/${target.dataset.chatRemoveMember}`, { method: 'DELETE' }); await loadChat(); state.chatRightInfoOpen = true; render(); } catch (error) { showToast(error.message); } } }); document.addEventListener('change', event => { const target = event.target; if (!(target instanceof Element)) return; if (target.matches('[data-chat-member-toggle]')) { const id = target.dataset.chatMemberToggle; const selected = new Set(state.chatGroupDraft.memberIds || []); if (target.checked) selected.add(id); else selected.delete(id); state.chatGroupDraft.memberIds = [...selected]; return; } if (target.matches('[data-chat-attachment]')) { const label = document.querySelector('[data-chat-file-name]'); if (label) label.textContent = target.files[0]?.name || ''; } }); document.addEventListener('submit', async event => { const form = event.target; if (!(form instanceof HTMLFormElement) || form.id !== 'create-group-chat-form') return; event.preventDefault(); const formData = new FormData(form); const input = { groupName: String(formData.get('groupName') || '').trim(), description: String(formData.get('description') || '').trim(), memberIds: state.chatGroupDraft.memberIds || [] }; if (!input.groupName) return; try { const result = await apiFetch('/api/chat/groups', { method: 'POST', body: JSON.stringify(input) }); state.chatGroupModalOpen = false; state.chatActive = { type: 'group', id: result.data.id }; showToast('Group chat created'); await loadChat(); } catch (error) { showToast(`Unable to create group: ${error.message}`); } }); }
/* Module 7 reports runtime: scoped, date-aware leadership reporting. */
state.reports = { loading: false, error: '', data: null, detail: null, filters: { dateRange: 'this_month', teamId: 'all', agentId: 'all', leadStatus: 'all', leadSource: 'all', followUpStatus: 'all' }, ...(state.reports || {}) };
function reportQueryString() { const filters = state.reports.filters; return new URLSearchParams(Object.entries(filters).filter(([, value]) => value && value !== 'all')).toString(); }
function reportDateText(value) { return value ? new Intl.DateTimeFormat('en-GB', { dateStyle: 'medium', timeZone: 'Asia/Karachi' }).format(new Date(value)) : '—'; }
function reportMetricCard(title, value, subtitle, variant = '') { return `<article class="report-metric-card ${variant}"><span class="report-metric-label">${AureumUI.escape(title)}</span><strong>${AureumUI.escape(String(value ?? '—'))}</strong><small>${AureumUI.escape(subtitle || 'Scoped to the selected report')}</small></article>`; }
function reportBars(points, suffix = '') { const max = Math.max(1, ...(points || []).map(point => Number(point.value) || Number(point.count) || 0)); return (points || []).map(point => { const value = Number(point.value ?? point.count) || 0; return `<div class="report-bar-row"><span>${AureumUI.escape(point.label || point.stage)}</span><div class="report-bar-track"><i style="width:${Math.round((value / max) * 100)}%"></i></div><b>${value}${suffix}</b></div>`; }).join('') || '<div class="empty-state">No report data found.</div>'; }
function reportSection(title, subtitle, body) { return `<section class="card report-section"><div class="section-title"><div><h3>${AureumUI.escape(title)}</h3><p>${AureumUI.escape(subtitle)}</p></div></div>${body}</section>`; }
function reportFilterOptions(options, selected) { return options.map(([value, label]) => `<option value="${AureumUI.escape(value)}" ${selected === value ? 'selected' : ''}>${AureumUI.escape(label)}</option>`).join(''); }

async function loadReports() { if (!state.authUser || !['SUPER_ADMIN', 'SALES_MANAGER'].includes(state.role)) return; state.reports = { ...state.reports, loading: true, error: '' }; render(); try { const result = await apiFetch(`/api/reports?${reportQueryString()}`); state.reports = { ...state.reports, loading: false, error: '', data: result.data }; } catch (error) { state.reports = { ...state.reports, loading: false, error: error.message, data: null }; } ensureEnhancedReportEvents(); render(); }

function renderReports() {
  ensureEnhancedReportEvents(); const data = state.reports.data; const filters = state.reports.filters; const dateOptions = window.AureumReportOptions?.dateRanges || [['today', 'Today'], ['yesterday', 'Yesterday'], ['this_week', 'This Week'], ['this_month', 'This Month'], ['last_month', 'Last Month'], ['custom', 'Custom Range']];
  if (state.reports.loading || !data) return pageHeader('Executive performance', 'Reports', '', '') + `<div class="card report-loading-state">${state.reports.error ? `<strong>Unable to load reports</strong><p>${AureumUI.escape(state.reports.error)}</p><button class="btn btn-secondary btn-sm" data-reload-reports>Retry</button>` : '<strong>Loading reports</strong><p>Preparing report data…</p>'}</div>`;
  const summary = data.summary || {}; const agentOptions = data.filters?.agents || []; const teamOptions = data.filters?.teams || []; const leadReport = data.leadReport || {}; const customerReport = data.customerReport || {}; const followUpReport = data.followUpReport || {};
  const agentRows = data.agentReports || []; const statusOptions = [['all', 'All lead statuses'], ...(window.AureumReportEnums?.leadStatuses || []).map(value => [value, value])]; const sourceOptions = [['all', 'All lead sources'], ...(window.AureumReportEnums?.leadSources || []).map(value => [value, value])]; const followUpOptions = [['all', 'All follow-up statuses'], ...(window.AureumReportEnums?.followUpStatuses || []).map(value => [value, value])];
  const customDates = filters.dateRange === 'custom' ? `<input type="date" data-report-start value="${AureumUI.escape(filters.startDate || '')}" aria-label="Report start date" /><input type="date" data-report-end value="${AureumUI.escape(filters.endDate || '')}" aria-label="Report end date" />` : '';
  const table = agentRows.length ? `<div class="table-wrap report-table-wrap"><table><thead><tr><th>Agent</th><th>Team</th><th>Assigned</th><th>Contacted</th><th>Hot</th><th>Follow-ups done</th><th>Overdue</th><th>Closed</th><th>Lost</th><th>Conversion</th><th>Last activity</th><th>Action</th></tr></thead><tbody>${agentRows.map(row => `<tr><td>${person(row.agentName, customerInitials(row.agentName), `${row.agentRole} · ${row.status}`)}</td><td>${AureumUI.escape(row.teamName || 'Unassigned')}</td><td>${row.assignedLeads}</td><td>${row.contactedLeads}</td><td>${row.hotLeads}</td><td>${row.followUpsCompleted}</td><td>${row.overdueFollowUps}</td><td>${row.closedDeals}</td><td>${row.lostLeads}</td><td><b>${row.conversionRate}%</b></td><td>${reportDateText(row.lastActivityAt)}</td><td><button class="table-action" data-report-agent="${AureumUI.escape(row.agentId)}">View details ${icons.arrow}</button></td></tr>`).join('')}</tbody></table></div>` : '<div class="empty-state"><strong>No agents found for this filter.</strong>Try another team or date range.</div>';
  const summaryCards = [reportMetricCard('Total agents', summary.totalAgents, data.scope === 'company' ? 'Company-wide scope' : 'Team scope', 'gold'), reportMetricCard('Assigned leads', summary.assignedLeads, 'Leads in selected range'), reportMetricCard('Contacted leads', summary.contactedLeads, 'Contact activity captured'), reportMetricCard('Hot leads', summary.hotLeads, 'High-intent pipeline', 'warning'), reportMetricCard('Follow-ups completed', summary.followUpsCompleted, 'Resolved touchpoints', 'success'), reportMetricCard('Overdue follow-ups', summary.overdueFollowUps, 'Action required', 'danger'), reportMetricCard('Closed deals', summary.closedDeals, 'Closed Won outcomes', 'success'), reportMetricCard('Conversion rate', `${summary.conversionRate || 0}%`, 'Closed Won / assigned leads', 'gold')].join('');
  return pageHeader('Executive performance', 'Reports', '', '') + `<section class="report-filter-bar card"><div class="report-filter-grid"><label>Date range<select data-report-date-range>${reportFilterOptions(dateOptions, filters.dateRange)}</select></label><label>Team<select data-report-team><option value="all">${data.scope === 'company' ? 'All teams' : 'My team'}</option>${teamOptions.map(team => `<option value="${AureumUI.escape(team)}" ${filters.teamId === team ? 'selected' : ''}>${AureumUI.escape(team === 'team_a' ? 'Sales Team A' : team === 'team_b' ? 'Sales Team B' : team)}</option>`).join('')}</select></label><label>Agent<select data-report-agent-filter><option value="all">All agents</option>${agentOptions.map(agent => `<option value="${AureumUI.escape(agent.id)}" ${filters.agentId === agent.id ? 'selected' : ''}>${AureumUI.escape(agent.name)}</option>`).join('')}</select></label><label>Lead status<select data-report-lead-status>${reportFilterOptions(statusOptions, filters.leadStatus)}</select></label><label>Lead source<select data-report-lead-source>${reportFilterOptions(sourceOptions, filters.leadSource)}</select></label><label>Follow-up status<select data-report-followup-status>${reportFilterOptions(followUpOptions, filters.followUpStatus)}</select></label>${customDates}</div><div class="report-filter-footer"><span>Generated ${reportDateText(data.meta?.generatedAt)} · ${AureumUI.escape(data.meta?.currency || 'PKR')}</span><button class="btn btn-secondary btn-sm" data-report-clear-filters>Clear filters</button></div></section><section class="report-metric-grid">${summaryCards}</section><section class="card report-table-card"><div class="table-head"><div><div class="eyebrow">PRIMARY REPORT</div><h3>Agent-wise performance</h3><p>Open an agent to inspect leads, customers, follow-ups, and activity.</p></div><div class="report-table-head-actions"><button class="btn btn-gold btn-sm" data-report-export="agent_report">Download CSV</button><button class="btn btn-secondary btn-sm" data-reload-reports>Refresh</button><span class="badge badge-neutral">${agentRows.length} visible agents</span></div></div>${table}</section><section class="report-section-grid">${reportSection('Lead report', 'Canonical lead statuses and source performance.', `<div class="report-mini-grid">${reportMetricCard('Total leads', leadReport.totalLeads, 'Selected range')}${reportMetricCard('New leads', leadReport.newLeads, 'New intake')}${reportMetricCard('Hot leads', leadReport.hotLeads, 'High intent', 'warning')}${reportMetricCard('Closed Won', leadReport.closedWon, `${leadReport.conversionRate || 0}% conversion`, 'success')}</div><div class="report-bars">${reportBars(data.charts?.leadSourcePerformance)}</div>`)}${reportSection('Customer report', 'Relationship health across the permitted scope.', `<div class="report-mini-grid">${reportMetricCard('Total customers', customerReport.totalCustomers, 'Selected range')}${reportMetricCard('Active customers', customerReport.activeCustomers, 'Active relationships', 'success')}${reportMetricCard('Hot customers', customerReport.hotCustomers, 'High intent', 'warning')}${reportMetricCard('Booking interested', customerReport.bookingInterestedCustomers, 'Commercial readiness', 'gold')}</div>`)}${reportSection('Follow-up report', 'Completion and recovery health for selected touchpoints.', `<div class="report-mini-grid">${reportMetricCard('Total follow-ups', followUpReport.totalFollowUps, 'Selected range')}${reportMetricCard('Completed', followUpReport.completedFollowUps, `${followUpReport.completionRate || 0}% completion`, 'success')}${reportMetricCard('Overdue', followUpReport.overdueFollowUps, 'Action required', 'danger')}${reportMetricCard('Rescheduled', followUpReport.rescheduledFollowUps, 'Needs review', 'warning')}</div><div class="report-bars">${reportBars(data.charts?.followUpStatusPerformance)}</div>`)}${reportSection('Conversion overview', 'Funnel stages use the canonical lead pipeline.', `<div class="report-bars conversion-bars">${reportBars(data.charts?.conversionOverview)}</div>`)}</section>`;
}

async function openReportAgent(id) { state.drawer = 'report-agent'; state.reports.detail = null; state.reportAgentTab = 'overview'; render(); try { const result = await apiFetch(`/api/reports/agents/${id}?${reportQueryString()}`); state.reports.detail = result.data; } catch (error) { state.reports.detail = { error: error.message }; } render(); }
function reportDetailTable(headers, rows, empty = 'No report data found.') { if (!rows?.length) return `<div class="empty-state">${AureumUI.escape(empty)}</div>`; return `<div class="table-wrap report-detail-table"><table><thead><tr>${headers.map(header => `<th>${AureumUI.escape(header)}</th>`).join('')}</tr></thead><tbody>${rows.map(row => `<tr>${row.map(cell => `<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`; }
function renderReportDrawer() { const detail = state.reports.detail; if (!detail) return `<div class="drawer-backdrop" data-close-drawer></div><aside class="drawer report-drawer"><div class="drawer-header"><h2>Loading report…</h2><button class="drawer-close" data-close-drawer>${icons.close}</button></div>${AureumUI.render.loading('Loading agent details')}</aside>`; if (detail.error) return `<div class="drawer-backdrop" data-close-drawer></div><aside class="drawer report-drawer"><div class="drawer-header"><h2>Unable to load agent</h2><button class="drawer-close" data-close-drawer>${icons.close}</button></div><div class="empty-state">${AureumUI.escape(detail.error)}</div></aside>`; const agent = detail.agent; const tab = state.reportAgentTab || 'overview'; const overview = detail.overview || {}; let body = ''; if (tab === 'leads') body = reportDetailTable(['Lead', 'Phone', 'Interested in', 'Source', 'Status', 'Created', 'Next follow-up'], detail.leads.map(item => [`<b>${AureumUI.escape(item.leadName)}</b>`, AureumUI.escape(item.phone || '—'), AureumUI.escape(item.interestedIn), AureumUI.escape(item.leadSource), badge(item.status), reportDateText(item.createdAt), AureumUI.escape(item.nextFollowUpAt || '—')])); else if (tab === 'follow-ups') body = reportDetailTable(['Customer', 'Type', 'Due', 'Time', 'Priority', 'Status'], detail.followUps.map(item => [`<b>${AureumUI.escape(item.customerName)}</b>`, AureumUI.escape(item.followUpType), reportDateText(item.dueDate), AureumUI.escape(item.dueTime || '—'), badge(item.priority), badge(item.status)])); else if (tab === 'customers') body = reportDetailTable(['Customer', 'Phone', 'Interested in', 'Status', 'Budget', 'Next follow-up'], detail.customers.map(item => [`<b>${AureumUI.escape(item.customerName)}</b>`, AureumUI.escape(item.phone || '—'), AureumUI.escape(item.interestedIn), badge(item.customerStatus), AureumUI.escape(String(item.budget || '—')), AureumUI.escape(item.nextFollowUpAt || '—')])); else if (tab === 'activity') body = `<div class="timeline">${(detail.activity || []).map(item => `<div class="timeline-item"><div class="timeline-dot"></div><div><b>${AureumUI.escape(item.activityType)}</b><div class="timeline-copy">${AureumUI.escape(item.description)}</div><div class="timeline-time">${reportDateText(item.createdAt)}</div></div></div>`).join('') || '<div class="empty-state">No activity recorded.</div>'}</div>`; else body = `<div class="report-drawer-metrics">${reportMetricCard('Assigned leads', overview.assignedLeads)}${reportMetricCard('Contacted leads', overview.contactedLeads)}${reportMetricCard('Hot leads', overview.hotLeads, 'High intent', 'warning')}${reportMetricCard('Completed follow-ups', overview.followUpsCompleted, 'Resolved', 'success')}${reportMetricCard('Overdue follow-ups', overview.overdueFollowUps, 'Action required', 'danger')}${reportMetricCard('Customers handled', overview.customersHandled)}${reportMetricCard('Closed deals', overview.closedDeals, 'Closed Won', 'success')}${reportMetricCard('Conversion rate', `${overview.conversionRate || 0}%`, 'Closed Won / assigned')}</div><div class="drawer-section"><h3>Recent activity</h3><div class="timeline">${(detail.activity || []).slice(0, 3).map(item => `<div class="timeline-item"><div class="timeline-dot"></div><div><b>${AureumUI.escape(item.activityType)}</b><div class="timeline-copy">${AureumUI.escape(item.description)}</div></div></div>`).join('') || '<div class="empty-state">No recent activity.</div>'}</div></div>`;
  return `<div class="drawer-backdrop" data-close-drawer></div><aside class="drawer report-drawer"><div class="drawer-header"><div><div class="eyebrow">Agent performance</div><h2>${AureumUI.escape(agent.agentName)}</h2><p class="page-subtitle">${AureumUI.escape(agent.agentRole)} · ${AureumUI.escape(agent.teamName || 'Unassigned')} · ${badge(agent.status)}</p></div><button class="drawer-close" data-close-drawer>${icons.close}</button></div><div class="drawer-section"><div class="header-actions"><button class="btn btn-gold btn-sm" data-agent-message="${AureumUI.escape(agent.agentId)}">Message agent</button><button class="btn btn-secondary btn-sm" data-report-export="agent_report">Download CSV</button></div></div><div class="tabs report-drawer-tabs">${['overview', 'leads', 'follow-ups', 'customers', 'activity'].map(item => `<button class="tab ${tab === item ? 'active' : ''}" data-report-tab="${item}">${item[0].toUpperCase() + item.slice(1)}</button>`).join('')}</div><div class="drawer-section">${body}</div></aside>`; }

async function downloadReport(reportType = 'agent_report') { const filters = state.reports?.filters || {}; const response = await fetch(apiUrl('/api/reports/export'), { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ reportType, ...filters }) }); if (!response.ok) { const body = await response.json().catch(() => ({})); throw new Error(body.error || 'Report download failed'); } const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `aureum-${reportType}.csv`; document.body.appendChild(link); link.click(); link.remove(); URL.revokeObjectURL(url); showToast('Report downloaded as CSV'); }
function ensureEnhancedReportEvents() { if (state.reportEventsBound) return; state.reportEventsBound = true; document.addEventListener('change', event => { const target = event.target; if (!(target instanceof Element) || !target.matches('[data-report-date-range], [data-report-team], [data-report-agent-filter], [data-report-lead-status], [data-report-lead-source], [data-report-followup-status], [data-report-start], [data-report-end]')) return; const filters = state.reports.filters; if (target.matches('[data-report-date-range]')) filters.dateRange = target.value; if (target.matches('[data-report-team]')) { filters.teamId = target.value; filters.agentId = 'all'; } if (target.matches('[data-report-agent-filter]')) filters.agentId = target.value; if (target.matches('[data-report-lead-status]')) filters.leadStatus = target.value; if (target.matches('[data-report-lead-source]')) filters.leadSource = target.value; if (target.matches('[data-report-followup-status]')) filters.followUpStatus = target.value; if (target.matches('[data-report-start]')) filters.startDate = target.value; if (target.matches('[data-report-end]')) filters.endDate = target.value; loadReports(); }); document.addEventListener('click', async event => { const target = event.target instanceof Element ? event.target.closest('[data-report-clear-filters], [data-report-export]') : null; if (!target) return; if (target.matches('[data-report-clear-filters]')) { state.reports.filters = { dateRange: 'this_month', teamId: 'all', agentId: 'all', leadStatus: 'all', leadSource: 'all', followUpStatus: 'all' }; loadReports(); return; } if (target.matches('[data-report-export]')) { try { await downloadReport(target.dataset.reportExport || 'agent_report'); } catch (error) { showToast(`Unable to export report: ${error.message}`); } } }); }
/* MODULE_8_USERS_ACCESS_RUNTIME */
state.users = state.users || { loading: false, error: '', items: [], teams: [], detail: null, filters: { search: '', role: 'All', status: 'All', inviteStatus: 'All', teamId: 'All', activityStatus: 'All' }, drawer: '' };
state.account = state.account || { loading: false, error: '', data: null };
function userText(value) { return AureumUI.escape(String(value ?? '')); }
function userDate(value) { if (!value) return 'Not available'; const date = new Date(value); return Number.isNaN(date.getTime()) ? 'Not available' : new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Karachi', dateStyle: 'medium', timeStyle: 'short' }).format(date); }
function userRoleLabel(value) { return ({ super_admin: 'Super Admin', sales_manager: 'Sales Manager', sales_agent: 'Sales Agent' })[value] || value || '—'; }
function userBadge(value) { return badge(value || 'Not available'); }
function userInitialsFor(item) { return String(item?.fullName || item?.full_name || 'Aureum').split(' ').map(part => part[0]).slice(0, 2).join('').toUpperCase(); }
function userMetric(label, value, copy, tone = '') { return `<div class="user-metric ${tone}"><span>${userText(label)}</span><strong>${userText(value)}</strong><small>${userText(copy)}</small></div>`; }
function userQuery() { const filters = state.users.filters || {}; return new URLSearchParams(Object.entries(filters).filter(([key, value]) => value && value !== 'All' && !(key === 'search' && !String(value).trim()))).toString(); }
async function loadUsers() { if (!state.authUser || !['SUPER_ADMIN', 'SALES_MANAGER'].includes(state.role)) return; state.users = { ...state.users, loading: true, error: '' }; render(); try { const result = await apiFetch(`/api/users?${userQuery()}`); state.users = { ...state.users, loading: false, error: '', items: result.data || [], teams: result.teams || [] }; } catch (error) { state.users = { ...state.users, loading: false, error: error.message, items: [] }; } render(); }
async function loadAgents() { return loadUsers(); }
async function loadUserDetail(id) { state.users.detail = null; state.drawer = 'user-detail'; render(); try { const result = await apiFetch(`/api/users/${id}`); state.users.detail = result; } catch (error) { state.users.detail = { error: error.message }; } render(); }
async function loadAccount() { if (!state.authUser) return; state.account = { ...state.account, loading: true, error: '' }; render(); try { const result = await apiFetch('/api/account/me'); state.account = { loading: false, error: '', data: result.user }; } catch (error) { state.account = { loading: false, error: error.message, data: null }; } render(); }
function userRoleOptions(selected = 'sales_agent') { return [['sales_manager', 'Sales Manager'], ['sales_agent', 'Sales Agent']].map(([value, label]) => `<option value="${value}" ${selected === value ? 'selected' : ''}>${label}</option>`).join(''); }
function userTeamOptions(selected = '') { return `<option value="">Unassigned</option>${(state.users.teams || []).map(team => `<option value="${userText(team.id)}" ${selected === team.id ? 'selected' : ''}>${userText(team.name)}</option>`).join('')}`; }
function renderUserForm(mode, item = {}) { const edit = mode === 'edit'; return `<form id="${edit ? 'user-edit-form' : 'user-create-form'}" class="user-form"><div class="form-grid"><div class="form-field full"><label>Full name</label><input name="fullName" required value="${userText(item.fullName || '')}" placeholder="e.g. Noor Fatima" /></div><div class="form-field"><label>Email</label><input name="email" type="email" ${edit ? 'readonly' : 'required'} value="${userText(item.email || '')}" placeholder="name@aureum.com" /></div><div class="form-field"><label>Phone</label><input name="phone" value="${userText(item.phone || '')}" placeholder="03xx-xxxxxxx" /></div><div class="form-field"><label>Role</label><select name="role" ${state.role === 'SALES_MANAGER' ? 'disabled' : ''}>${userRoleOptions(item.role || 'sales_agent')}</select></div><div class="form-field"><label>Team</label><select name="teamId" ${state.role === 'SALES_MANAGER' ? 'disabled' : ''}>${userTeamOptions(item.teamId || '')}</select></div><div class="form-field"><label>Status</label><select name="status"><option ${item.status === 'Pending' || !item.status ? 'selected' : ''}>Pending</option><option ${item.status === 'Active' ? 'selected' : ''}>Active</option><option ${item.status === 'Inactive' ? 'selected' : ''}>Inactive</option><option ${item.status === 'Suspended' ? 'selected' : ''}>Suspended</option></select></div>${!edit ? '<div class="form-field full"><label>Temporary password <small>(optional)</small></label><input name="temporaryPassword" placeholder="Generated securely when empty" /></div><label class="user-check full"><input type="checkbox" name="sendAccessEmail" checked /> Send access email</label><label class="user-check full"><input type="checkbox" name="requirePasswordChangeOnFirstLogin" checked /> Require password change on first login</label>' : ''}</div><div class="drawer-actions"><button type="button" class="btn btn-secondary" data-user-close>Cancel</button><button type="submit" class="btn btn-gold">${edit ? 'Save changes' : 'Create user'}</button></div></form>`; }
function renderUserDrawer() { if (state.drawer === 'user-create') return `<div class="drawer-backdrop" data-user-close></div><aside class="drawer user-drawer"><div class="drawer-header"><div><div class="eyebrow">Access management</div><h2>Add new user</h2><p class="page-subtitle">Create a scoped CRM account with controlled access.</p></div><button class="drawer-close" data-user-close>${icons.close}</button></div>${renderUserForm('create')}</aside>`; if (state.drawer === 'user-edit') { const detail = state.users.detail?.user || {}; return `<div class="drawer-backdrop" data-user-close></div><aside class="drawer user-drawer"><div class="drawer-header"><div><div class="eyebrow">User profile</div><h2>Edit user</h2></div><button class="drawer-close" data-user-close>${icons.close}</button></div>${renderUserForm('edit', detail)}</aside>`; } const detail = state.users.detail; if (!detail) return `<div class="drawer-backdrop" data-user-close></div><aside class="drawer user-drawer"><div class="drawer-header"><h2>Loading user…</h2><button class="drawer-close" data-user-close>${icons.close}</button></div><div class="empty-state">Loading profile and audit history…</div></aside>`; if (detail.error) return `<div class="drawer-backdrop" data-user-close></div><aside class="drawer user-drawer"><div class="drawer-header"><h2>Unable to load user</h2><button class="drawer-close" data-user-close>${icons.close}</button></div><div class="empty-state">${userText(detail.error)}</div></aside>`; const item = detail.user; const audit = (detail.auditLogs || []).map(log => `<div class="user-audit-row"><b>${userText(log.action)}</b><span>${userText(log.description)}</span><small>${userDate(log.createdAt)}</small></div>`).join('') || '<div class="empty-state">No audit logs yet.</div>'; const active = item.status === 'Active'; return `<div class="drawer-backdrop" data-user-close></div><aside class="drawer user-drawer"><div class="drawer-header"><div class="user-drawer-identity"><div class="person-avatar">${userInitialsFor(item)}</div><div><div class="eyebrow">User detail</div><h2>${userText(item.fullName)}</h2><p class="page-subtitle">${userText(item.roleLabel)} · ${userText(item.teamName || 'Unassigned')}</p><div class="user-badges">${userBadge(item.status)} ${userBadge(item.inviteStatus)}</div></div></div><button class="drawer-close" data-user-close>${icons.close}</button></div><div class="user-detail-actions"><button class="btn btn-secondary btn-sm" data-user-action="edit" data-user-id="${userText(item.id)}">Edit user</button><button class="btn btn-secondary btn-sm" data-user-action="send" data-user-id="${userText(item.id)}">Send access email</button><button class="btn btn-secondary btn-sm" data-user-action="reset" data-user-id="${userText(item.id)}">Reset password</button><button class="btn btn-secondary btn-sm" data-user-action="toggle" data-user-id="${userText(item.id)}">${active ? 'Deactivate' : 'Activate'}</button></div><section class="user-detail-section"><h3>Profile</h3><div class="user-detail-grid"><div><small>Email</small><b>${userText(item.email)}</b></div><div><small>Phone</small><b>${userText(item.phone || 'Not provided')}</b></div><div><small>Role</small><b>${userText(item.roleLabel)}</b></div><div><small>Team</small><b>${userText(item.teamName || 'Unassigned')}</b></div></div></section><section class="user-detail-section"><h3>Access</h3><div class="user-detail-grid"><div><small>Invite status</small><b>${userText(item.inviteStatus)}</b></div><div><small>Access email sent</small><b>${userDate(item.accessEmailSentAt)}</b></div><div><small>Temporary password expires</small><b>${userDate(item.temporaryPasswordExpiresAt)}</b></div><div><small>Must change password</small><b>${item.mustChangePassword ? 'Required' : 'Complete'}</b></div><div><small>Last login</small><b>${userDate(item.lastLoginAt)}</b></div><div><small>Last activity</small><b>${userDate(item.lastActivityAt)}</b></div></div></section><section class="user-detail-section"><h3>Audit log</h3><div class="user-audit-list">${audit}</div></section></aside>`; }
function renderUsers() { const items = state.users.items || []; const filters = state.users.filters || {}; const total = items.length; const active = items.filter(item => item.status === 'Active').length; const inactive = items.filter(item => ['Inactive', 'Suspended'].includes(item.status)).length; const managers = items.filter(item => item.role === 'sales_manager').length; const agents = items.filter(item => item.role === 'sales_agent').length; const pending = items.filter(item => ['Pending', 'Sent'].includes(item.inviteStatus)).length; const table = state.users.loading ? '<div class="user-empty-state">Loading users and access status…</div>' : state.users.error ? `<div class="user-empty-state"><strong>Unable to load users</strong><p>${userText(state.users.error)}</p><button class="btn btn-secondary btn-sm" data-users-reload>Retry</button></div>` : !items.length ? '<div class="user-empty-state"><strong>No users found.</strong><p>Try clearing a filter or create a new scoped user.</p></div>' : `<div class="table-wrap users-table-wrap"><table><thead><tr><th>User</th><th>Role</th><th>Team</th><th>Status</th><th>Invite</th><th>Last login</th><th>Last activity</th><th>Actions</th></tr></thead><tbody>${items.map(item => `<tr><td>${person(userText(item.fullName), userInitialsFor(item), `${userText(item.email)} · ${userText(item.phone || 'No phone')}`)}</td><td>${userText(item.roleLabel)}</td><td>${userText(item.teamName || 'Unassigned')}</td><td>${userBadge(item.status)}</td><td>${userBadge(item.inviteStatus)}</td><td>${userDate(item.lastLoginAt)}</td><td><span class="user-activity"><i class="presence-dot ${String(item.activityStatus).toLowerCase()}"></i>${userText(item.activityStatus)}</span><small>${userDate(item.lastActivityAt)}</small></td><td><button class="table-action" data-user-action="view" data-user-id="${userText(item.id)}">View</button></td></tr>`).join('')}</tbody></table></div>`; return pageHeader('Access management', 'Users', 'Manage CRM roles, teams, invitations, and personal account security.', '<button class="btn btn-gold" data-user-create>+ Add user</button><button class="btn btn-secondary" data-users-reload>Refresh</button>') + `<section class="user-summary-grid">${userMetric('Total users', total, state.role === 'SALES_MANAGER' ? 'Own-team scope' : 'Company scope', 'gold')}${userMetric('Active users', active, 'Available access', 'success')}${userMetric('Inactive users', inactive, 'Access retained')}${userMetric('Sales managers', managers, 'Leadership accounts')}${userMetric('Sales agents', agents, 'Relationship officers')}${userMetric('Pending invites', pending, 'Awaiting access')}</section><section class="card users-table-card"><div class="user-filter-bar"><div class="search-box">${icons.search}<input data-users-search placeholder="Search name, email, or phone" value="${userText(filters.search || '')}" /></div><select data-users-role><option value="All">All roles</option><option value="sales_manager" ${filters.role === 'sales_manager' ? 'selected' : ''}>Sales Manager</option><option value="sales_agent" ${filters.role === 'sales_agent' ? 'selected' : ''}>Sales Agent</option></select><select data-users-status><option>All</option>${['Active', 'Inactive', 'Pending', 'Suspended'].map(value => `<option ${filters.status === value ? 'selected' : ''}>${value}</option>`).join('')}</select><select data-users-invite><option>All</option>${['Not Sent', 'Pending', 'Sent', 'Accepted', 'Expired', 'Failed'].map(value => `<option ${filters.inviteStatus === value ? 'selected' : ''}>${value}</option>`).join('')}</select><select data-users-team><option value="All">All teams</option>${(state.users.teams || []).map(team => `<option value="${userText(team.id)}" ${filters.teamId === team.id ? 'selected' : ''}>${userText(team.name)}</option>`).join('')}</select><button class="btn btn-secondary btn-sm" data-users-clear>Clear</button></div>${table}</section>`; }
function renderMyAccount() { const item = state.account.data || state.authUser || {}; return pageHeader('Personal workspace', 'My Account', 'Keep your profile, password, and login activity current.', '<button class="btn btn-secondary" data-screen="change-password">Change password</button>') + `<section class="account-grid"><div class="card account-card"><div class="section-title"><div><div class="eyebrow">Profile information</div><h3>Your CRM identity</h3></div><span class="badge badge-neutral">${userText(userRoleLabel(item.role))}</span></div>${state.account.loading ? '<div class="empty-state">Loading account profile…</div>' : `<form id="account-profile-form"><div class="form-grid"><div class="form-field full"><label>Full name</label><input name="fullName" required value="${userText(item.fullName || item.full_name || '')}" /></div><div class="form-field"><label>Email <small>(read-only)</small></label><input value="${userText(item.email || '')}" readonly /></div><div class="form-field"><label>Phone</label><input name="phone" value="${userText(item.phone || '')}" /></div></div><button class="btn btn-gold" type="submit">Save profile</button></form>`}</div><div class="card account-card"><div class="section-title"><div><div class="eyebrow">Security</div><h3>Account status</h3></div></div><div class="account-security-list"><div><span>Status</span><b>${userBadge(item.status || 'Active')}</b></div><div><span>Last login</span><b>${userDate(item.lastLoginAt || item.last_login_at)}</b></div><div><span>Last activity</span><b>${userDate(item.lastActivityAt || item.last_activity_at)}</b></div><div><span>Team</span><b>${userText(item.teamName || 'Leadership')}</b></div></div><button class="btn btn-secondary" data-screen="change-password">Update password</button></div></section>`; }
function renderChangePassword() { return pageHeader('Personal security', 'Change Password', 'Use a strong password to protect your Aureum CRM account.', '') + `<section class="card account-password-card"><div class="eyebrow">Required security step</div><h2>Set a new password</h2><p class="page-subtitle">Minimum 8 characters with uppercase, lowercase, number, and special character.</p><form id="change-password-form"><div class="form-field"><label>Current password</label><input name="currentPassword" type="password" required autocomplete="current-password" /></div><div class="form-field"><label>New password</label><input name="newPassword" type="password" required autocomplete="new-password" /></div><div class="form-field"><label>Confirm new password</label><input name="confirmPassword" type="password" required autocomplete="new-password" /></div><div class="password-policy">Your new password must not match the current temporary password.</div><div class="drawer-actions"><button class="btn btn-secondary" type="button" data-screen="my-account">Cancel</button><button class="btn btn-gold" type="submit">Update password</button></div></form></section>`; }
function renderDrawer() { if (['user-detail', 'user-create', 'user-edit'].includes(state.drawer)) return renderUserDrawer(); if (state.drawer === 'customer') return window.renderCustomerDrawer ? window.renderCustomerDrawer() : renderCustomerDrawer(); if (state.drawer === 'followup' || state.drawer === 'create-followup') return window.renderFollowupDrawer ? window.renderFollowupDrawer() : renderFollowupDrawer(); if (state.drawer === 'lead') return window.renderLeadDrawer ? window.renderLeadDrawer() : renderLeadDrawer(); return legacyRenderDrawer(); }
function navigate(screen) { if (routePaths[screen]) window.history.pushState({}, '', routePaths[screen]); if (!canAccess(screen)) { state.drawer = null; state.deniedPath = screen; state.screen = 'unauthorized'; } else { state.drawer = null; state.screen = screen; } render(); if (screen === 'agents') loadUsers(); if (screen === 'my-account') loadAccount(); if (screen === 'dashboard') loadDashboard(); if (screen === 'leads') loadLeads(false); if (screen === 'my-leads') loadLeads(true); if (screen === 'customers') loadCustomers(); if (screen === 'follow-ups') loadFollowups(); if (screen === 'team-chat') loadChat(); if (screen === 'reports') loadReports(); }
function render() { if (!state.ready) { app.innerHTML = '<div class="loading-screen"><div class="brand-mark">A</div><div>Loading Aureum CRM…</div></div>'; return; } if (!state.authUser || state.screen === 'login') { app.innerHTML = renderLogin(); bind(); return; } if (state.authUser.must_change_password && state.screen !== 'change-password') { state.screen = 'change-password'; window.history.replaceState({}, '', routePaths['change-password']); } if (state.screen !== 'unauthorized' && !canAccess(state.screen)) { state.deniedPath = state.screen; state.screen = 'unauthorized'; } if (state.screen === 'unauthorized') { app.innerHTML = layout(renderAccessDenied()); bind(); return; } let content = renderDashboard(); if (state.screen === 'leads') content = renderLeads(false); if (state.screen === 'my-leads') content = renderLeads(true); if (state.screen === 'add-lead') content = renderAddLead(); if (state.screen === 'customers') content = renderCustomers(); if (state.screen === 'follow-ups') content = renderFollowups(); if (state.screen === 'team-chat') content = renderChat(); if (state.screen === 'reports') content = renderReports(); if (state.screen === 'agents') content = renderUsers(); if (state.screen === 'my-account') content = renderMyAccount(); if (state.screen === 'change-password') content = renderChangePassword(); if (state.screen === 'settings') content = renderSettings(); app.innerHTML = layout(content); bind(); ensureUsersEvents(); }
function userActionTarget(id) { return (state.users.items || []).find(item => item.id === id) || state.users.detail?.user; }
async function handleUserAction(action, id) { const item = userActionTarget(id); if (!item) return; if (action === 'view') { await loadUserDetail(id); return; } if (action === 'edit') { await loadUserDetail(id); state.drawer = 'user-edit'; render(); return; } if (action === 'report') { window.history.pushState({}, '', `/reports?agentId=${encodeURIComponent(id)}`); state.screen = 'reports'; render(); loadReports(); return; } if (action === 'message') { navigate('team-chat'); return; } if (action === 'toggle') { const next = item.status === 'Active' ? 'Inactive' : 'Active'; if (next === 'Inactive' && !window.confirm(`Deactivate ${item.fullName}?`)) return; try { await apiFetch(`/api/users/${id}/status`, { method: 'PATCH', body: JSON.stringify({ status: next }) }); showToast(`User ${next === 'Active' ? 'activated' : 'deactivated'}.`); await loadUsers(); if (state.drawer) await loadUserDetail(id); } catch (error) { showToast(error.message); } return; } if (['send', 'resend', 'reset'].includes(action)) { try { const endpoint = action === 'send' ? 'send-access-email' : action === 'resend' ? 'resend-access-email' : 'reset-password'; const result = await apiFetch(`/api/users/${id}/${endpoint}`, { method: 'POST', body: JSON.stringify({ sendAccessEmail: true, requirePasswordChangeOnFirstLogin: true }) }); showToast(result.email?.message || 'Access email sent successfully.'); await loadUsers(); if (state.drawer) await loadUserDetail(id); } catch (error) { showToast(error.message); } } }
function ensureUsersEvents() { if (state.usersEventsBound) return; state.usersEventsBound = true; document.addEventListener('click', async event => { const target = event.target instanceof Element ? event.target.closest('[data-user-create], [data-user-close], [data-user-action], [data-users-reload], [data-users-clear]') : null; if (!target) return; if (target.matches('[data-user-create]')) { state.drawer = 'user-create'; render(); return; } if (target.matches('[data-user-close]')) { state.drawer = null; render(); return; } if (target.matches('[data-users-reload]')) { loadUsers(); return; } if (target.matches('[data-users-clear]')) { state.users.filters = { search: '', role: 'All', status: 'All', inviteStatus: 'All', teamId: 'All', activityStatus: 'All' }; loadUsers(); return; } if (target.matches('[data-user-action]')) await handleUserAction(target.dataset.userAction, target.dataset.userId); }); document.addEventListener('input', event => { if (event.target instanceof Element && event.target.matches('[data-users-search]')) { state.users.filters.search = event.target.value; loadUsers(); } }); document.addEventListener('change', event => { const target = event.target; if (!(target instanceof Element)) return; const map = { '[data-users-role]': 'role', '[data-users-status]': 'status', '[data-users-invite]': 'inviteStatus', '[data-users-team]': 'teamId' }; const key = Object.keys(map).find(selector => target.matches(selector)); if (key) { state.users.filters[map[key]] = target.value; loadUsers(); } }); document.addEventListener('submit', async event => { const form = event.target; if (!(form instanceof HTMLFormElement)) return; if (form.id === 'user-create-form') { event.preventDefault(); const data = Object.fromEntries(new FormData(form).entries()); try { await apiFetch('/api/users', { method: 'POST', body: JSON.stringify({ ...data, sendAccessEmail: data.sendAccessEmail === 'on', requirePasswordChangeOnFirstLogin: data.requirePasswordChangeOnFirstLogin === 'on' }) }); state.drawer = null; showToast('User created and access email sent successfully.'); await loadUsers(); } catch (error) { showToast(error.message); } } if (form.id === 'user-edit-form') { event.preventDefault(); const data = Object.fromEntries(new FormData(form).entries()); try { await apiFetch(`/api/users/${state.users.detail.user.id}`, { method: 'PATCH', body: JSON.stringify(data) }); state.drawer = null; showToast('User profile updated.'); await loadUsers(); } catch (error) { showToast(error.message); } } if (form.id === 'account-profile-form') { event.preventDefault(); const data = Object.fromEntries(new FormData(form).entries()); try { const result = await apiFetch('/api/account/me', { method: 'PATCH', body: JSON.stringify(data) }); state.authUser = { ...state.authUser, ...result.user }; state.account.data = result.user; showToast('Profile updated successfully.'); render(); } catch (error) { showToast(error.message); } } if (form.id === 'change-password-form') { event.preventDefault(); const data = Object.fromEntries(new FormData(form).entries()); try { const result = await apiFetch('/api/account/change-password', { method: 'POST', body: JSON.stringify(data) }); state.authUser = { ...state.authUser, ...result.user, must_change_password: false, mustChangePassword: false }; showToast(result.message); state.screen = 'dashboard'; window.history.pushState({}, '', '/dashboard'); render(); loadDashboard(); } catch (error) { showToast(error.message); } } }); }
/* MODULE_6_ENHANCED_RUNTIME */
async function boot() { await window.aureumFinalBoot(); if (state.authUser && state.screen === 'team-chat') loadChat(); if (state.authUser && state.screen === 'reports') loadReports(); if (state.authUser && state.screen === 'agents') loadAgents(); }
boot();
